// OrchestratorServiceServer is the server API for OrchestratorService service.
// All implementations should embed UnimplementedOrchestratorServiceServer
// for forward compatibility.
type OrchestratorServiceServer interface {
	// Session Operations
	SpawnSession(context.Context, *SpawnSessionRequest) (*SpawnSessionResponse, error)
	PromptSession(context.Context, *PromptSessionRequest) (*PromptSessionResponse, error)
	SessionStatus(context.Context, *SessionStatusRequest) (*SessionStatusResponse, error)
	CloseSession(context.Context, *CloseSessionRequest) (*CloseSessionResponse, error)
	ListSessions(context.Context, *ListSessionsRequest) (*ListSessionsResponse, error)
	// RotateSessionAccount moves one session onto a different pooled provider
	// account. Rotation also happens automatically when a turn fails on a
	// classified provider limit; this is the operator-initiated door to the
	// same verb ("this seat is bad, move my session now").
	RotateSessionAccount(context.Context, *RotateSessionAccountRequest) (*RotateSessionAccountResponse, error)
	// Task Operations
	CreateTask(context.Context, *CreateTaskRequest) (*CreateTaskResponse, error)
	GetTask(context.Context, *GetTaskRequest) (*GetTaskResponse, error)
	ListTasks(context.Context, *ListTasksRequest) (*ListTasksResponse, error)
	ClaimTask(context.Context, *ClaimTaskRequest) (*ClaimTaskResponse, error)
	CompleteTask(context.Context, *CompleteTaskRequest) (*CompleteTaskResponse, error)
	BlockTask(context.Context, *BlockTaskRequest) (*BlockTaskResponse, error)
	ReadmitTask(context.Context, *ReadmitTaskRequest) (*ReadmitTaskResponse, error)
	// DeleteTask removes a task and releases its source reservation.
	// Authorized as the task-record write verb: deleting a task is the
	// inverse of creating one, and the permission vocabulary go-qrdb owns
	// carries no separate delete action for this family.
	DeleteTask(context.Context, *DeleteTaskRequest) (*DeleteTaskResponse, error)
	DecomposeTask(context.Context, *DecomposeTaskRequest) (*DecomposeTaskResponse, error)
	// Job Operations
	StartJob(context.Context, *OrchestratorStartJobRequest) (*OrchestratorStartJobResponse, error)
	GetJobStatus(context.Context, *OrchestratorGetJobStatusRequest) (*OrchestratorGetJobStatusResponse, error)
	CancelJob(context.Context, *OrchestratorCancelJobRequest) (*OrchestratorCancelJobResponse, error)
	ListJobs(context.Context, *OrchestratorListJobsRequest) (*OrchestratorListJobsResponse, error)
	// Event Streaming
	SubscribeJobEvents(*SubscribeJobEventsRequest, grpc.ServerStreamingServer[JobEvent]) error
	// Backend Operations
	ListBackends(context.Context, *OrchestratorListBackendsRequest) (*OrchestratorListBackendsResponse, error)
	// ListRunners returns every registered JobRunner and the ordered,
	// non-terminal states it declares. This is REGISTRY data, not tenant
	// data: the runners a daemon can drive are the same for every caller,
	// which is why the request carries no tenant. Gated on the same
	// orchestrator:status the REST route GET /api/v1/orchestrator/runners
	// is gated on.
	ListRunners(context.Context, *OrchestratorListRunnersRequest) (*OrchestratorListRunnersResponse, error)
	// Health Operations
	Health(context.Context, *OrchestratorHealthRequest) (*OrchestratorHealthResponse, error)
	// Fleet Management
	RegisterFleetNode(context.Context, *RegisterFleetNodeRequest) (*RegisterFleetNodeResponse, error)
	GetFleetNode(context.Context, *GetFleetNodeRequest) (*GetFleetNodeResponse, error)
	ListFleetNodes(context.Context, *ListFleetNodesRequest) (*ListFleetNodesResponse, error)
	RemoveFleetNode(context.Context, *RemoveFleetNodeRequest) (*RemoveFleetNodeResponse, error)
	FleetNodeHeartbeat(context.Context, *FleetNodeHeartbeatRequest) (*FleetNodeHeartbeatResponse, error)
	// Session event ingest (Phase 3). Daemon-side agents open a bidi stream
	// and push each session event as PushEventRequest; the control plane acks
	// with EventAck carrying the accepted sequence. At-least-once delivery:
	// daemon re-sends events the control plane hasn't ack'd after reconnect.
	PushEvents(grpc.BidiStreamingServer[PushEventRequest, PushEventAck]) error
	// Session event subscription (Phase 4). Operators attach to a session
	// to see prompts, assistant output, tool calls, file ops in real time.
	// When from_sequence > 0 the stream begins with the historical replay
	// from that sequence, then transitions to live tail when follow is true.
	SubscribeSessionEvents(*SubscribeSessionRequest, grpc.ServerStreamingServer[SessionEventEnvelope]) error
	// GetSessionConversation returns one page of a session's CONVERSATION:
	// who said what, which tools ran, and what each answer cost. It is the
	// coarser sibling of SubscribeSessionEvents, which serves the raw log —
	// every fragment, thought and presence change — in the shape a live
	// attacher needs. A streaming answer is many events and exactly one turn
	// here, and the page boundary always falls between turns.
	//
	// NAMED FOR WHAT IT RETURNS, not for the route it is reached on. The SDK
	// already has a GetSessionHistory that pages the raw EVENT log, and two
	// verbs called history returning two different shapes would be worse than
	// one verb whose name does not match its URL. Its REST route is
	// GET /orchestrator/sessions/{id}/history, because that is the resource an
	// operator reaches for.
	GetSessionConversation(context.Context, *GetSessionConversationRequest) (*GetSessionConversationResponse, error)
	// GetSpendReport returns one scope of the CONSUMPTION LEDGER: the tokens
	// spent under it, the drill-down to the level below, and the allowance
	// status of every pooled account that paid.
	//
	// ONE VERB FOR EVERY LEVEL, because the ledger's attribution chain is a
	// PATH — tenant/project/task/job/session/round — and "the project's
	// spend" and "the job's spend" are the same prefix scan at two depths.
	// Four RPCs over one scan would be four places for a drill-down's
	// arithmetic to stop agreeing with itself.
	//
	// WHAT IT DOES NOT CLAIM. Every money figure is accompanied by how many
	// entries it covers (priced_entries, billed_entries), and zero is a dash
	// rather than a zero. Likewise policy_status distinguishes an account
	// with no cap from one this deployment could not read. go-quicbaas#791.
	GetSpendReport(context.Context, *GetSpendReportRequest) (*GetSpendReportResponse, error)
	// GetTenantSpendPolicy returns the tenant's own spend limits and its
	// live usage against each window, over every turn charged to it.
	GetTenantSpendPolicy(context.Context, *GetTenantSpendPolicyRequest) (*TenantSpendPolicyResponse, error)
	// SetTenantSpendPolicy replaces the tenant's own spend limits; limits
	// with no windows make the tenant unmetered. go-quicbaas#1058.
	SetTenantSpendPolicy(context.Context, *SetTenantSpendPolicyRequest) (*TenantSpendPolicyResponse, error)
	// Inference runs a stateless prompt against a named backend without
	// requiring a prior session. The response is aggregated and returned
	// as a single InferenceResponse. For streaming use InferenceStream.
	Inference(context.Context, *InferenceRequest) (*InferenceResponse, error)
	// InferenceStream runs a stateless prompt against a named backend and
	// streams InferenceChunk frames until the backend signals completion.
	// The final frame carries final=true and the aggregated stop_reason.
	InferenceStream(*InferenceRequest, grpc.ServerStreamingServer[InferenceChunk]) error
	// SpawnChildJob fans out a child job from a parent job's lead agent.
	// The calling agent MUST be the registered lead of parent_job_id; any
	// other caller receives PERMISSION_DENIED (not_lead_of_parent).
	SpawnChildJob(context.Context, *SpawnChildJobRequest) (*SpawnChildJobResponse, error)
	// SubmitTaskArtifacts attaches typed artifacts to a completed task.
	// Artifacts exceeding the server-side InlineLimit are stored in the
	// QuicBaaS KV store; the task record carries only the Ref.
	SubmitTaskArtifacts(context.Context, *SubmitTaskArtifactsRequest) (*SubmitTaskArtifactsResponse, error)
	// ListTaskArtifacts returns artifact metadata for a task without resolving
	// large Refs to their content.
	ListTaskArtifacts(context.Context, *ListTaskArtifactsRequest) (*ListTaskArtifactsResponse, error)
	// GetTaskArtifact retrieves a single named artifact, resolving kv_key Refs
	// to their full byte content.
	GetTaskArtifact(context.Context, *GetTaskArtifactRequest) (*GetTaskArtifactResponse, error)
	// GetCostSettings returns a tenant's runtime cost settings — the
	// electricity rate and engine draws its local inference is costed from —
	// and the rates in force once layered over the configuration.
	// go-quicbaas#1058.
	GetCostSettings(context.Context, *GetCostSettingsRequest) (*CostSettingsResponse, error)
	// SetCostSettings replaces a tenant's runtime cost settings; settings
	// that override nothing restore the configuration.
	SetCostSettings(context.Context, *SetCostSettingsRequest) (*CostSettingsResponse, error)
}

